/bin/bash -lc "python3 - <<'PY'
import json, urllib.request, urllib.parse, re, html, time
records=json.load(open('/workspace/encode_atac_files.json'))
gms=[r['sid'] for r in records if r['sid'].startswith('GM')]
def get(url):
    for attempt in range(5):
        try:
            req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            return urllib.request.urlopen(req).read()
        except Exception as e:
            if attempt==4:
                print('FAIL',url,e); raise
            time.sleep(2*(attempt+1))
mapping={}
for gm in gms:
    q=urllib.parse.urlencode({'db':'biosample','term':f'\"{gm}\"[All Fields]','retmode':'json'})
    txt=get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?'+q)
    j=json.loads(txt); ids=j['esearchresult']['idlist']
    found=None; evidence=None
    if ids:
        q=urllib.parse.urlencode({'db':'biosample','id':','.join(ids),'retmode':'json'})
        txt=get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?'+q)
        j=json.loads(txt)
        for uid in ids:
            d=j['result'].get(uid)
            if not d: continue
            s=d.get('sampledata','')
            idmap={db:html.unescape(re.sub('<["'^>]+>'"','',v)).strip() for db,v in re.findall(r'<Id db=\"(["'^"]+)"[''^>]*>(.*?)</Id>'"',s)}
            if idmap.get('Coriell')==gm:
                g1=idmap.get('1000G')
                if g1:
                    found=g1; evidence=(d.get('accession'),idmap); break
    mapping[gm]=found
    print(gm,'->',found,evidence)
    time.sleep(0.4)
json.dump(mapping, open('/workspace/gm_to_1000g_mapping_ncbi.json','w'), indent=2)
print('total',len(mapping),'mapped',sum(v is not None for v in mapping.values()))
print('not found',[k for k,v in mapping.items() if not v])
PY"

