/bin/bash -lc "python3 - <<'PY'
import urllib.request, urllib.parse, json, re, html, time
for gm in ['GM18858','GM18520','GM18505','GM18508','GM18517']:
    term=f'{gm}[All Fields] AND Coriell[All Fields]'
    url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?'+urllib.parse.urlencode({'db':'biosample','term':term,'retmax':'100','retmode':'json'})
    j=json.load(urllib.request.urlopen(url)); ids=j['esearchresult']['idlist']
    print(gm, 'count',len(ids), ids[:10])
    if ids:
      url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?'+urllib.parse.urlencode({'db':'biosample','id':','.join(ids),'retmode':'json'})
      j=json.load(urllib.request.urlopen(url))
      for uid in ids:
        d=j['result'].get(uid)
        if d:
          s=d['sampledata']; idmap={db:html.unescape(re.sub('<["'^>]+>'"','',v)).strip() for db,v in re.findall(r'<Id db=\"(["'^"]+)"[''^>]*>(.*?)</Id>'"',s)}
          if idmap.get('Coriell')==gm:
            print(' ',d.get('accession'),d.get('title')[:80],idmap)
            break
    time.sleep(0.5)
PY"

