/bin/bash -lc "python3 - <<'PY'
import json, urllib.request, urllib.parse, re, html, time, sys
records=json.load(open('/workspace/encode_atac_files.json'))
gms=[r['sid'] for r in records if r['sid'].startswith('GM')]

def fetch(url, tries=6):
    for i in range(tries):
        try:
            req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            return urllib.request.urlopen(req).read()
        except Exception as e:
            if i==tries-1:
                print('ERROR',url,e,file=sys.stderr); raise
            time.sleep(1.5*(i+1))

def esearch(term, retmax='100'):
    q=urllib.parse.urlencode({'db':'biosample','term':term,'retmax':retmax,'retmode':'json'})
    txt=fetch('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?'+q)
    j=json.loads(txt); return j['esearchresult']['idlist']

def esummary(ids):
    q=urllib.parse.urlencode({'db':'biosample','id':','.join(ids),'retmode':'json'})
    txt=fetch('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?'+q)
    return json.loads(txt)['result']

def parse_idmap(s):
    return {db:html.unescape(re.sub('<["'^>]+>'"','',v)).strip() for db,v in re.findall(r'<Id db=\"(["'^"]+)"[''^>]*>(.*?)</Id>'"',s)}

mapping={}
for gm in gms:
    ids=esearch(f'{gm}[All Fields] AND 1000G[All Fields]')
    found=None; evidence=None
    if ids:
        res=esummary(ids)
        for uid in ids:
            d=res.get(uid)
            if not d: continue
            idmap=parse_idmap(d.get('sampledata',''))
            if idmap.get('Coriell')==gm and idmap.get('1000G'):
                found=idmap['1000G']; evidence=(d.get('accession'),idmap); break
    mapping[gm]=found
    print(f'{gm}\\t{found}\\t{evidence}', flush=True)
    time.sleep(0.35)
json.dump(mapping, open('/workspace/gm_to_1000g_mapping_ncbi.json','w'), indent=2)
print('mapped',sum(v is not None for v in mapping.values()),'of',len(mapping))
print('none',[k for k,v in mapping.items() if not v])
PY"

